// Helper function to create a line object
function createLineObj(spacing, velocity, color, y, speedMultiplier) {
  let lineObj = [];

  let numSquares = Math.ceil((width + spacing) / (squareSize + spacing));
  let actualSpacing = (width - numSquares * squareSize) / (numSquares - 1);

  for (let i = 0; i < numSquares; i++) {
    let x = i * (squareSize + actualSpacing);

    lineObj.push({ x, y, velocity, color, speedMultiplier });
  }

  return lineObj;
}

