  // Apply the color shift values
  hsbColor[0] = (hsbColor[0] + hueShift + 360) % 360;
  hsbColor[1] = constrain(hsbColor[1] + saturationShift, 0, 100);
  hsbColor[2] = constrain(hsbColor[2] + brightnessShift, 0, 100);

  let rgbColor = hsbToRgb(hsbColor[0], hsbColor[1], hsbColor[2]);
  return rgbColor;
}

// Helper function to convert RGB color to HSB color
function rgbToHsb(r, g, b) {
  r /= 255;
  g /= 255;
  b /= 255;

  let maxVal = Math.max(r, g, b);
  let minVal = Math.min(r, g, b);
  let hue,
    saturation,
    brightness = maxVal;

  let delta = maxVal - minVal;

  if (delta !== 0) {
    saturation = delta / maxVal;

    if (maxVal === r) {
      hue = (g - b) / delta;
    } else if (maxVal === g) {
      hue = 2 + (b - r) / delta;
    } else {
      hue = 4 + (r - g) / delta;
    }

    hue *= 60;

    if (hue < 0) {
      hue += 360;
    }
  } else {
    saturation = 0;
    hue = 0;
  }

  return [hue, saturation * 100, brightness * 100];
}

// Helper function to convert HSB color to RGB color
function hsbToRgb(h, s, b) {
  s /= 100;
  b /= 100;

  let r, g, bl;

  if (s === 0) {
    r = g = bl = b;
  } else {
    let hue = h / 60;
    let i = Math.floor(hue);
    let f = hue - i;
    let p = b * (1 - s);
    let q = b * (1 - s * f);
    let t = b * (1 - s * (1 - f));

    switch (i) {
      case 0:
        r = b;
        g = t;
        bl = p;
        break;
      case 1:
        r = q;
        g = b;
        bl = p;
        break;
      case 2:
        r = p;
        g = b;
        bl = t;
        break;
      case 3:
        r = p;
        g = q;
        bl = b;
        break;
      case 4:
        r = t;
        g = p;
        bl = b;
        break;
      default:
        r = b;
        g = p;
        bl = q;
        break;
    }
  }

  return [r * 255, g * 255, bl * 255];
}
